suppressPackageStartupMessages({library(Seurat);library(Matrix);library(harmony);library(jsonlite);library(ggplot2)})
args<-commandArgs(TRUE);stopifnot(length(args)==1);root<-Sys.getenv('PROJECT_ROOT');stopifnot(nchar(root)>0)
cfg<-fromJSON(args[1]);out<-file.path(root,cfg$output);stopifnot(!dir.exists(out));dir.create(out)
set.seed(20261106);started<-format(Sys.time(),tz='UTC',usetz=TRUE)
mark<-function(stage){z<-list(UTC=format(Sys.time(),tz='UTC',usetz=TRUE),stage=stage,lineage=cfg$lineage);write_json(z,file.path(out,'progress.json'),auto_unbox=TRUE);cat(toJSON(z,auto_unbox=TRUE),'\n');flush.console()}
mark('load_clean_counts');counts<-Read10X_h5(file.path(root,cfg$input_10x),use.names=TRUE,unique.features=TRUE)
meta<-read.delim(gzfile(file.path(root,cfg$input_meta)),row.names=1,check.names=FALSE,stringsAsFactors=FALSE)
stopifnot(ncol(counts)==cfg$n_cells,nrow(counts)==cfg$n_genes,identical(colnames(counts),rownames(meta)))
symbols<-rownames(counts);feature_id<-paste0('QCFEATURE',seq_along(symbols));rownames(counts)<-feature_id
write.table(data.frame(feature_id=feature_id,gene_symbol=symbols),file.path(out,'feature_id_gene_symbol_map.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
obj<-CreateSeuratObject(counts=counts,meta.data=meta,min.cells=0,min.features=0,project=paste0('V7_clean_',cfg$lineage))
mark('full_RNA_normalization');obj<-NormalizeData(obj,normalization.method='LogNormalize',scale.factor=10000,verbose=FALSE)
model_symbols<-read.delim(file.path(root,cfg$model_genes),stringsAsFactors=FALSE)$gene_symbol;features<-feature_id[match(model_symbols,symbols)];stopifnot(!anyNA(features))
de_symbols<-read.delim(file.path(root,cfg$DE_genes),stringsAsFactors=FALSE)$gene_symbol;de_features<-feature_id[match(de_symbols,symbols)];stopifnot(!anyNA(de_features))
mark('new_lineage_HVG');obj[['HVG_model']]<-CreateAssayObject(counts=GetAssayData(obj,assay='RNA',layer='counts')[features,,drop=FALSE]);obj<-FindVariableFeatures(obj,assay='HVG_model',selection.method='vst',nfeatures=2000,verbose=FALSE)
hvg<-VariableFeatures(obj[['HVG_model']]);VariableFeatures(obj[['RNA']])<-hvg;DefaultAssay(obj)<-'RNA'
write.table(data.frame(feature_id=hvg,gene_symbol=symbols[match(hvg,feature_id)]),file.path(out,'HVG_source_robust.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
mark('new_PCA');obj<-ScaleData(obj,assay='RNA',features=hvg,verbose=FALSE);obj<-RunPCA(obj,assay='RNA',features=hvg,npcs=50,seed.use=20261106,verbose=FALSE)
mark('new_raw_graph');obj<-FindNeighbors(obj,reduction='pca',dims=1:30,graph.name=c('raw_nn','raw_snn'),verbose=FALSE);obj<-FindClusters(obj,graph.name='raw_snn',resolution=.4,random.seed=20261106,verbose=FALSE)
mark('new_source_Harmony');obj<-RunHarmony(obj,group.by.vars='gse_id',reduction.use='pca',dims.use=1:30,reduction.save='harmony_source',project.dim=FALSE,verbose=FALSE)
mark('new_source_graph');obj<-FindNeighbors(obj,reduction='harmony_source',dims=1:30,graph.name=c('source_nn','source_snn'),verbose=FALSE);res<-c(.2,.4,.6,.8);obj<-FindClusters(obj,graph.name='source_snn',resolution=res,random.seed=20261106,verbose=FALSE)
mark('new_UMAP');obj<-RunUMAP(obj,reduction='harmony_source',dims=1:30,reduction.name='umap_source',reduction.key='UMAPclean_',seed.use=20261106,verbose=FALSE)
md<-obj[[]];cols<-grep('^(raw|source)_snn_res',colnames(md),value=TRUE)
tab<-do.call(rbind,lapply(cols,function(cn){z<-table(md[[cn]]);data.frame(graph=cn,cluster=names(z),n_cells=as.integer(z))}));write.table(tab,file.path(out,'cluster_resolution_counts.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
src<-do.call(rbind,lapply(cols,function(cn){z<-table(md[[cn]],md$gse_id);data.frame(graph=cn,cluster=rownames(z),n_cells=rowSums(z),n_gse=rowSums(z>0),max_gse_fraction=apply(z,1,max)/rowSums(z))}));write.table(src,file.path(out,'cluster_source_concentration.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
write.table(cbind(cell_id=rownames(md),md),gzfile(file.path(out,'metadata_PRIVATE.tsv.gz')),sep='\t',quote=FALSE,row.names=FALSE)
cross<-as.data.frame(table(old_cluster=md$old_review_cluster,new_cluster=md$source_snn_res.0.4));cross<-cross[cross$Freq>0,];write.table(cross,file.path(out,'old_to_clean_cluster_crosswalk.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
mark('RNA_DE_on_common_measured_features');Idents(obj)<-'source_snn_res.0.4';DefaultAssay(obj)<-'RNA';de<-FindAllMarkers(obj,assay='RNA',slot='data',features=de_features,min.pct=.1,min.diff.pct=.25,logfc.threshold=.25,return.thresh=.01,only.pos=FALSE,test.use='wilcox',verbose=FALSE)
de$feature_id<-de$gene;de$gene<-symbols[match(de$feature_id,feature_id)];stopifnot(!anyNA(de$gene));write.table(de,file.path(out,'RNA_FindAllMarkers_common_measured.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
pdf(file.path(out,'clean_embedding_diagnostics.pdf'),width=12,height=9);print(ElbowPlot(obj,ndims=50));print(DimPlot(obj,reduction='umap_source',group.by='source_snn_res.0.4',label=TRUE,raster=TRUE));print(DimPlot(obj,reduction='umap_source',group.by='old_review_cluster',raster=TRUE));print(DimPlot(obj,reduction='umap_source',group.by='gse_id',raster=TRUE)+NoLegend());dev.off()
mark('save_private_model');saveRDS(obj,file.path(out,'clean_refit_seurat_PRIVATE.rds'),compress=FALSE)
result<-list(status='completed_clean_lineage_refit',UTC_start=started,UTC_end=format(Sys.time(),tz='UTC',usetz=TRUE),lineage=cfg$lineage,n_cells=ncol(obj),n_RNA_features=nrow(obj[['RNA']]),n_HVG=length(hvg),n_model_feature_candidates=length(features),n_common_measured_DE_features=length(de_features),n_PCA=50,graph_PCs=30,resolutions=res,marker_resolution=.4,normalization='Full-library RNA LogNormalize 10000',source_covariate='gse_id; source sensitivity, not verified physical technology',reference_labels_used_in_fit=FALSE,regressed_variables=character(),seed=20261106,final_identity_assignment='pending_marker_review')
write_json(result,file.path(out,'complete.json'),auto_unbox=TRUE,pretty=TRUE);mark('completed')
